using System.Collections.Generic;

// Cola de turno de enemigos en un juego por turnos
Queue<string> turnos = new Queue<string>();

// Enqueue — agrega al FINAL de la cola
turnos.Enqueue("Goblin");    // Cola: [Goblin]
turnos.Enqueue("Orco");      // Cola: [Goblin, Orco]
turnos.Enqueue("Dragón");    // Cola: [Goblin, Orco, Dragón]

// Peek — lee el FRENTE sin eliminar
string siguiente = turnos.Peek(); // "Goblin"
Debug.Log(turnos.Count);          // 3

// Dequeue — elimina y devuelve el FRENTE
string turnoActual = turnos.Dequeue(); // devuelve "Goblin"
Debug.Log(turnos.Count);               // 2 — [Orco, Dragón]

// Verificar antes de Dequeue
if (turnos.Count > 0)
{
    string proximo = turnos.Dequeue(); // "Orco"
}

