public class TurnManager : MonoBehaviour
{
    private Queue<Character> turnQueue = new Queue<Character>();

    public void IniciarRonda(List<Character> personajes)
    {
        foreach (Character c in personajes)
            turnQueue.Enqueue(c);
    }

    public Character SiguienteEnAtacar()
    {
        return turnQueue.Dequeue();
    }
}

